const d=window.PORTFOLIO;const main=document.querySelector('main');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=u=>{try{const x=new URL(u,location.origin);return ['http:','https:'].includes(x.protocol)?x.href:''}catch{return ''}};const projects=d.projects.length?d.projects:d.examples;const example=!d.projects.length;const name=d.name||'Your name';const btn=(href,label,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="${esc(href)}">${label} <span aria-hidden="true">↗</span></a>`;const heading=(label,title,desc='')=>`<div class="page-title"><span class="eyebrow">${label}</span><h1>${title}</h1><p class="lead">${desc}</p></div>`;const empty=t=>`<div class="empty">${t}</div>`;
function art(p){if(p.image&&safe(p.image))return `<img src="${esc(safe(p.image))}" alt="${esc(p.name)} project screenshot" loading="lazy" style="width:100%;height:205px;object-fit:cover">`;return `<div class="art ${esc(p.art||'dashboard')}" role="img" aria-label="${esc(p.name)} illustrative concept artwork">${p.art==='identity'?'<strong>form.</strong><small>A STUDY IN SIMPLICITY</small>':`<div class="mini-window"><b>${p.art==='workspace'?'Your workspace':'Overview'}</b><div class="mini-bar"></div>${p.art==='workspace'?'<i></i><i></i><i></i><i></i>':'<div class="mini-grid"><i></i><i></i><i></i></div><div class="chart"></div>'}</div>`}</div>`}
const cards=items=>items.map(p=>`<article class="card"><a href="/projects/${esc(p.id)}" tabindex="-1" aria-hidden="true">${art(p)}</a><div class="card-body"><div class="meta"><span>${esc(p.category)}</span><span>${esc(p.year)}</span></div><h3><a href="/projects/${esc(p.id)}">${esc(p.name)} ↗</a></h3><p>${esc(p.description)}</p><div class="tags">${p.technologies.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="small-note">${esc(p.status)} · ${esc(p.type)}</p></div></article>`).join('');
function cv(){return d.cv&&safe(d.cv)?`<div class="actions"><a class="button" href="${esc(safe(d.cv))}" download>Download CV ↓</a><a class="button secondary" href="${esc(safe(d.cv))}" target="_blank" rel="noopener">View CV online ↗</a></div>`:empty('The latest CV PDF has not been provided yet. Download and online viewing will be available once it is added.');}
function skills(){return d.skills.length?`<div class="grid">${d.skills.map(s=>`<article class="skill-box"><span class="icon" aria-hidden="true">⌘</span><h3>${esc(s.category)}</h3><div class="tags">${s.items.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></article>`).join('')}</div>`:empty('Verified skills are awaiting the creator’s details. Skills will be grouped by discipline without invented proficiency percentages.');}
function about(){return `<div class="two"><div><span class="eyebrow">A LITTLE ABOUT ME</span><h2>Curiosity meets<br>purposeful creation.</h2><p>${esc(d.bio||'This space will introduce the creator’s background, approach, areas of expertise and professional goals.')}</p>${btn('/about','More about me',true)}</div><dl class="facts">${[['Full name',d.name],['Professional title',d.title],['Location',d.location],['Email',d.email],['Phone',d.phone],['Specialization',d.specialization],['Experience',d.yearsExperience],['Occupation',d.occupation]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'To be provided')}</dd></div>`).join('')}</dl></div>`}
function timeline(items,type){return items.length?`<div class="timeline">${items.map(x=>`<article><span class="eyebrow">${esc(x.dates||x.year)}</span><h3>${esc(x.position||x.degree||x.name)}</h3><p>${esc(x.organization||x.institution)}${x.location?' · '+esc(x.location):''}</p><p>${esc(x.description||'')}</p>${x.responsibilities?`<ul>${x.responsibilities.map(y=>`<li>${esc(y)}</li>`).join('')}</ul>`:''}${x.credentialId?`<p>Credential ID: ${esc(x.credentialId)}</p>`:''}</article>`).join('')}</div>`:empty(`${type} will appear here once the creator supplies verified details.`);}
function contact(){return `${heading('LET’S CONNECT','Good things start<br>with a conversation.','Have a project in mind, a question, or an opportunity? Get in touch.')}<section class="two section"><div><h2>Let’s make something<br>meaningful.</h2><p>Contact information will appear below when provided.</p>${[['Email',d.email],['Phone',d.phone],['Location',d.location]].map(([k,v])=>`<p><span class="eyebrow">${k}</span><br>${esc(v||'To be provided')}</p>`).join('')}</div><form id="contact-form"><div class="two"><div class="field"><label for="name">Name</label><input id="name" name="name" required maxlength="100" autocomplete="name"></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required maxlength="254" autocomplete="email"></div></div><div class="field"><label for="subject">Subject</label><input id="subject" name="subject" required maxlength="200"></div><div class="field"><label for="message">Message</label><textarea id="message" name="message" required minlength="10" maxlength="5000"></textarea></div><div class="trap" aria-hidden="true"><label for="company">Leave this empty</label><input id="company" name="company" tabindex="-1" autocomplete="off"></div><button class="button" ${d.contactEndpoint?'':'disabled'}>Send message ↗</button><p id="form-status" role="status" class="small-note">${d.contactEndpoint?'Your details are used only to respond to this message.':'Message delivery is awaiting an email service connection. The form cannot send messages yet.'}</p></form></section>`;}
function render(){let path=decodeURI(location.pathname).replace(/\/$/,'')||'/';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===path));let title='Home';if(path==='/'){main.innerHTML=`<section class="hero"><div><div class="pill"><span class="dot"></span> THE INTERSECTION OF DESIGN & TECHNOLOGY</div><h1>Hi, I’m ${esc(name)}.<br>I create with<br><em>purpose.</em></h1><p class="lead">${esc(d.bio||'A space for thoughtful ideas, useful digital experiences, and the work that brings them to life.')}</p><div class="actions">${btn('/projects','Explore my work')}${btn('/contact','Let’s talk',true)}</div><a class="text-link" href="/cv">View résumé & credentials ↓</a></div><div class="hero-art">${d.photo&&safe(d.photo)?`<img src="${esc(safe(d.photo))}" alt="Portrait of ${esc(name)}">`:'<div class="portrait-placeholder"><strong>d.</strong><small>YOUR PORTRAIT HERE</small></div>'}<div class="floating top"><b>⌘</b> Design × development</div><div class="floating"><b>Ideas into experiences.</b>One thoughtful detail at a time.</div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE PORTFOLIO</span><h2>Selected work<span style="color:var(--accent)">.</span></h2><p>${example?'Illustrative concepts showing the portfolio layout. These are not claimed as completed client work.':'A selection of projects, process and practical solutions.'}</p></div><a class="text-link" href="/projects">All projects ↗</a></div><div class="grid">${cards(projects.slice(0,3))}</div></section><section class="section">${about()}</section><section class="section"><div class="section-head"><div><span class="eyebrow">MY TOOLKIT</span><h2>Skills with intention.</h2></div><a class="text-link" href="/skills">Explore skills ↗</a></div>${skills()}</section><div class="callout"><div><span class="eyebrow">HAVE SOMETHING IN MIND?</span><h2>Let’s turn your next idea<br>into something real.</h2></div>${btn('/contact','Start a conversation')}</div>`;}else if(path==='/about'){title='About';main.innerHTML=heading('BEHIND THE WORK','A little about me.','Background, interests and a considered approach to creating digital experiences.')+`<section class="section">${about()}</section>`;}else if(path==='/skills'){title='Skills';main.innerHTML=heading('TOOLS & CAPABILITIES','The skills behind<br>the work.','Technical capabilities and professional strengths, presented honestly.')+`<section class="section">${skills()}</section>`;}else if(path==='/experience'||path==='/education'){let exp=path==='/experience';title=exp?'Experience':'Education';main.innerHTML=heading(exp?'THE JOURNEY':'LEARNING & GROWTH',exp?'Experience that<br>shapes the work.':'Education & credentials.','A record of professional growth and learning.')+`<section class="section">${timeline(exp?d.experience:d.education,title)}</section>`;}else if(path==='/cv'){title='CV';main.innerHTML=heading('THE FULL PICTURE','My curriculum vitae.','View professional background, experience and qualifications in one document.')+`<section class="section">${cv()}</section>`;}else if(path==='/contact'){title='Contact';main.innerHTML=contact();const f=document.querySelector('form');f.addEventListener('submit',async e=>{e.preventDefault();if(!d.contactEndpoint||!safe(d.contactEndpoint))return;const payload=Object.fromEntries(new FormData(f));if(payload.company)return;const status=document.querySelector('#form-status'),b=f.querySelector('button');b.disabled=true;status.textContent='Sending…';try{const r=await fetch(safe(d.contactEndpoint),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error();status.textContent='Your message has been sent. Thank you!';f.reset()}catch{status.textContent='The message could not be sent. Please try again or use the email address listed here.'}finally{b.disabled=false}});}else if(path==='/projects'){title='Projects';const options=field=>[...new Set(projects.map(p=>p[field]))].sort().map(x=>`<option>${esc(x)}</option>`).join('');main.innerHTML=heading('IDEAS INTO EXPERIENCES','Explore the work.',example?'Illustrative concepts for preview. Replace these with your real projects before sharing your professional portfolio.':'Browse projects by name, technology, category, year and type.')+`<div class="filters"><div><label class="filter-label" for="search">SEARCH PROJECTS</label><input id="search" type="search" placeholder="Search name, technology, category…"></div>${[['category','Category'],['year','Year'],['type','Type']].map(([key,label])=>`<div><label class="filter-label" for="${key}">${label.toUpperCase()}</label><select id="${key}"><option value="">All ${label.toLowerCase()}s</option>${options(key)}</select></div>`).join('')}</div><p id="result-count" class="small-note" aria-live="polite"></p><section class="grid" id="results" style="padding-bottom:70px"></section>`;const update=()=>{const q=document.querySelector('#search').value.trim().toLowerCase();const found=projects.filter(p=>[p.name,p.description,p.category,p.type,p.year,...p.technologies].join(' ').toLowerCase().includes(q)&&['category','year','type'].every(k=>!document.getElementById(k).value||String(p[k])===document.getElementById(k).value));document.querySelector('#results').innerHTML=found.length?cards(found):empty('No matching projects. Try a different search or clear the filters.');document.querySelector('#result-count').textContent=`${found.length} project${found.length===1?'':'s'} found`;};document.querySelectorAll('.filters input,.filters select').forEach(x=>x.addEventListener('input',update));update();}else if(path.startsWith('/projects/')){const p=projects.find(x=>x.id===path.split('/')[2]);if(p){title=p.name;main.innerHTML=`<a class="back" href="/projects">← All projects</a>${heading(esc(p.category)+' / '+esc(p.year),esc(p.name),esc(p.description))}<div class="detail-art">${art(p)}</div><section class="section two"><div><span class="eyebrow">PROJECT OVERVIEW</span><h2>From problem to purpose.</h2>${example?'<p class="notice">Illustrative concept. This example is not a completed professional project.</p>':''}<h3>The problem</h3><p>${esc(p.problem)}</p><h3>The solution</h3><p>${esc(p.solution)}</p><h3>Features</h3><ul>${p.features.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${p.screenshots?.map(x=>`<img src="${esc(safe(x))}" alt="${esc(p.name)} screenshot" loading="lazy" style="max-width:100%">`).join('')||''}</div><div class="skill-box"><span class="eyebrow">PROJECT DETAILS</span><h3>Role</h3><p>${esc(p.role)}</p><h3>Status</h3><p>${esc(p.status)}</p><h3>Technologies</h3><div class="tags">${p.technologies.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="actions">${[['url','Live project'],['github','Source code'],['demo','Demo'],['documentation','Documentation']].filter(([k])=>p[k]&&safe(p[k])).map(([k,l])=>btn(safe(p[k]),l,true)).join('')}</div></div></section>`;}else{title='Project not found';main.innerHTML=heading('404','Project not found.','This project does not exist.')+btn('/projects','Browse projects');}}else{title='Page not found';main.innerHTML=heading('404','Page not found.','The page you are looking for does not exist.')+btn('/','Return home');}document.title=`${title} | ${d.name||'Creator & Developer'} Portfolio`;}
let theme;try{theme=localStorage.getItem('portfolio-theme')}catch{}document.documentElement.dataset.theme=theme||'light';document.querySelector('.theme').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('portfolio-theme',next)}catch{}});document.querySelector('.menu').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});document.querySelector('#footer-name').textContent=(d.name?d.name+' · ':'')+d.title;const socials=[['linkedin','LinkedIn'],['github','GitHub']].filter(([k])=>d[k]&&safe(d[k]));if(socials.length)document.querySelector('#socials').innerHTML=socials.map(([k,l])=>`<a href="${esc(safe(d[k]))}" target="_blank" rel="noopener">${l} ↗</a>`).join('');render();
